import{_ as a,o as e,c as o,a2 as s}from"./chunks/framework.G0y0PQA7.js";const i="/relio/shots/ko/cat-tabs.png",r="/relio/shots/ko/cat-multi-select.png",f=JSON.parse('{"title":"카테고리로 나눠 보기","description":"","frontmatter":{},"headers":[],"relativePath":"quick/categories.md","filePath":"quick/categories.md"}'),c={name:"quick/categories.md"};function l(n,t,p,g,d,_){return e(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="카테고리로-나눠-보기" tabindex="-1">카테고리로 나눠 보기 <a class="header-anchor" href="#카테고리로-나눠-보기" aria-label="Permalink to &quot;카테고리로 나눠 보기&quot;">​</a></h1><p>테이블이 많으면 업무 영역별 카테고리로 나눠 필요한 부분만 봅니다.</p><ol><li><p><strong>카테고리 만들기</strong> — 팔레트에서 카테고리(<kbd>C</kbd>)를 고르고 캔버스에서 끌어 영역을 만듭니다. 영역 안에 놓인 테이블이 그 카테고리에 속합니다. 이름과 목록은 모델 › 카테고리 ▸ › 카테고리 관리…에서 고칩니다.</p></li><li><p><strong>카테고리 탭으로 보기</strong> — 캔버스 아래 카테고리 탭에서 &quot;전체&quot; 또는 카테고리를 누릅니다. 카테고리 탭은 그 카테고리에 속한 것만 보여 주고, 탭마다 보던 위치를 기억합니다.</p><figure class="shot" data-scene="cat-tabs"><img src="'+i+'" alt="캔버스 아래 카테고리 탭 — 전체와 카테고리별 탭" loading="lazy"><figcaption>캔버스 아래 카테고리 탭 — 전체와 카테고리별 탭</figcaption></figure></li><li><p><strong>여러 카테고리 함께 보기</strong> — 다른 탭을 <kbd>Ctrl</kbd>+클릭(macOS는 <kbd>⌘</kbd>+클릭)하면 그 카테고리를 더하거나 뺍니다. 그냥 클릭하면 그 탭 하나만 봅니다.</p><figure class="shot" data-scene="cat-multi-select"><img src="'+r+'" alt="두 카테고리 탭을 함께 고른 모습 — 아래 줄이 굵은 탭이 주 카테고리" loading="lazy"><figcaption>두 카테고리 탭을 함께 고른 모습 — 아래 줄이 굵은 탭이 주 카테고리</figcaption></figure></li></ol><p>여러 개를 함께 볼 때는 아래 줄이 굵은 탭(마지막에 고른 카테고리)이 주 카테고리입니다. 이 화면에서 새로 만들거나 붙여 넣은 테이블은 주 카테고리에 들어갑니다.</p><div class="info custom-block"><p class="custom-block-title">참고</p><p>여러 개를 고른 상태는 파일에 저장하지 않습니다. 파일에는 주 카테고리 하나만 남으므로 ERMaster와 섞어 써도 그대로입니다.</p></div><p><strong>자세히</strong> → <a href="/relio/features/categories">카테고리</a></p>',6)])])}const m=a(c,[["render",l]]);export{f as __pageData,m as default};
